<div class="filter-card card"><form method="get"><input type="hidden" name="page" value="tasks"><div class="filter-grid task-filters"><input name="search" placeholder="Search task title..." value="<?=e($filters['search'])?>"><select name="project_id"><option value="">All project</option><?php foreach($projects as $p):?><option value="<?=$p['id']?>" <?=((string)$filters['project_id']===(string)$p['id']?'selected':'')?>><?=e($p['name'])?></option><?php endforeach;?></select><select name="status"><option value="">All status</option><?php foreach(['To Do','In Progress','Done'] as $s):?><option <?=($filters['status']===$s?'selected':'')?>><?=$s?></option><?php endforeach;?></select><select name="priority"><option value="">All priority</option><?php foreach(['Low','Medium','High'] as $s):?><option <?=($filters['priority']===$s?'selected':'')?>><?=$s?></option><?php endforeach;?></select><select name="sort"><option value="due_asc" <?=($filters['sort']==='due_asc'?'selected':'')?>>Due date ↑</option><option value="due_desc" <?=($filters['sort']==='due_desc'?'selected':'')?>>Due date ↓</option></select><button class="btn btn-primary">Apply</button><a class="btn" href="?page=tasks">Reset</a></div></form></div>
<div class="page-actions"><p class="muted">Pagination 10 data per halaman.</p><?php if($currentUser['role']==='Admin'):?><a class="btn btn-primary" href="?page=tasks&action=create">+ Add Task</a><?php endif;?></div>
<div class="card"><div class="table-wrap"><table><thead><tr><th>Task</th><th>Project</th><th>Assignee</th><th>Status</th><th>Priority</th><th>Due Date</th><th>Action</th></tr></thead><tbody><?php foreach($result['items'] as $t):?><tr><td><a class="link" href="?page=tasks&action=view&id=<?=$t['id']?>"><?=e($t['title'])?></a></td><td><?=e($t['project_name'])?></td><td><?=e($t['assignee_name'])?></td><td><span class="badge status-<?=strtolower(str_replace(' ','-',$t['status']))?>"><?=e($t['status'])?></span></td><td><span class="badge priority-<?=strtolower($t['priority'])?>"><?=e($t['priority'])?></span></td><td><?=e($t['due_date'])?></td><td class="actions"><?php if($currentUser['role']==='Admin'):?><a class="btn btn-sm" href="?page=tasks&action=edit&id=<?=$t['id']?>">Edit</a><form method="post" action="?page=tasks&action=delete&id=<?=$t['id']?>" onsubmit="return confirm('Hapus task ini?')"><?=$csrfField?><button class="btn btn-sm danger-btn">Delete</button></form><?php else:?><form class="inline-form" method="post" action="?page=tasks&action=status&id=<?=$t['id']?>"><?=$csrfField?><select name="status"><option <?=($t['status']==='To Do'?'selected':'')?>>To Do</option><option <?=($t['status']==='In Progress'?'selected':'')?>>In Progress</option><option <?=($t['status']==='Done'?'selected':'')?>>Done</option></select><button class="btn btn-sm btn-primary">Update</button></form><?php endif;?></td></tr><?php endforeach;?><?php if(!$result['items']):?><tr><td colspan="7" class="empty">Tidak ada task yang sesuai.</td></tr><?php endif;?></tbody></table></div><div class="pagination"><?php $qs=$_GET;unset($qs['current_page']);if($result['page']>1):$qs['current_page']=$result['page']-1;?><a class="page-btn" href="?<?=http_build_query(array_merge(['page'=>'tasks'],$qs))?>">‹ Prev</a><?php endif;?><?php for($i=1;$i<=$result['pages'];$i++):$qs['current_page']=$i;?><a class="page-btn <?=$i===$result['page']?'current':''?>" href="?<?=http_build_query(array_merge(['page'=>'tasks'],$qs))?>"><?=$i?></a><?php endfor;?><?php if($result['page']<$result['pages']):$qs['current_page']=$result['page']+1;?><a class="page-btn" href="?<?=http_build_query(array_merge(['page'=>'tasks'],$qs))?>">Next ›</a><?php endif;?></div></div>
